<script>
document.addEventListener('DOMContentLoaded', () => {
    const initInfiniteSlider = (selector, speed = 1) => {
        const container = document.querySelector(selector);
        if (!container) return;

        const cloneItems = () => {
            const items = Array.from(container.children);
            items.forEach(item => {
                const clone = item.cloneNode(true);
                container.appendChild(clone);
            });
        };

        cloneItems();
        cloneItems();

        let currentPosition = 0;
        let isPaused = false;

        const animate = () => {
            if (!isPaused) {
                currentPosition += speed;
                if (currentPosition >= container.scrollWidth / 3) {
                    currentPosition = 0;
                }
                container.scrollLeft = currentPosition;
            }
            requestAnimationFrame(animate);
        };

        container.addEventListener('mouseenter', () => isPaused = true);
        container.addEventListener('mouseleave', () => isPaused = false);
        window.addEventListener('load', animate);
    };

    // 2. Review-slider Manual Slider
    // const initManualSlider = () => {
    //     const slider = document.getElementById('review-slider');
    //     const prevBtn = document.getElementById('tp-prev');
    //     const nextBtn = document.getElementById('tp-next');
    //     if (!slider || !prevBtn || !nextBtn) return;

    //     const scrollAmount = 394; // card width + gap

    //     prevBtn.addEventListener('click', () => {
    //         slider.scrollLeft -= scrollAmount;
    //     });

    //     nextBtn.addEventListener('click', () => {
    //         slider.scrollLeft += scrollAmount;
    //     });
    // };

    // initManualSlider();
    initInfiniteSlider('.siteVelocity__slider', 1.2);
    initInfiniteSlider('.siteVelocity__ticker', 1.3);
    initInfiniteSlider('.growthStories__slider', 1.8);



    $('.popup-youtube').magnificPopup({
        disableOn: 700,
        type: 'iframe',
        mainClass: 'mfp-fade',
        removalDelay: 160,
        preloader: false
    });

});
</script>